// Helper: Extract all pattern string variants for robust cross-dataset matching
export function getPatternVariants(s: string): string[] {
  if (!s) return [];
  const t = s.trim().replace(/^20\d\d\//, '');
  const set = new Set<string>([t]);
  if (t.includes('/')) {
    const parts = t.split('/');
    set.add(parts[parts.length - 1]);
    if (parts.length >= 2) {
      set.add(parts.slice(-2).join('/'));
    }
  }
  return Array.from(set);
}

// Helper: Calculate DE Pattern Statistics across the historical dataset
export function getDEPatternStats(de: string): PatternStats {
  const vars = getPatternVariants(de);
  let wins = 0;
  let losses = 0;

  for (const g of HISTORICAL_GAMES) {
    if (vars.includes(g.winnerDE)) wins++;
    if (vars.includes(g.loserDE)) losses++;
  }

  // Fallback to official totals if exact counts match official reference
  if (wins === 0) {
    for (const v of vars) {
      if (OFFICIAL_WINNING_DE_STATS[v]) {
        wins = OFFICIAL_WINNING_DE_STATS[v];
        break;
      }
    }
  }

  const total = wins + losses;
  const winPct = total > 0 ? Math.round((wins / total) * 1000) / 10 : 50.0;

  return {
    pattern: de,
    wins,
    losses,
    total,
    winPct
  };
}

// Helper: Calculate Day Pattern Statistics across the historical dataset
export function getDayPatternStats(day: string): PatternStats {
  const vars = getPatternVariants(day);
  let wins = 0;
  let losses = 0;

  for (const g of HISTORICAL_GAMES) {
    if (vars.includes(g.winnerDay)) wins++;
    if (vars.includes(g.loserDay)) losses++;
  }

  if (wins === 0) {
    for (const v of vars) {
      if (OFFICIAL_WINNING_DAY_STATS[v]) {
        wins = OFFICIAL_WINNING_DAY_STATS[v];
        break;
      }
    }
  }

  const total = wins + losses;
  const winPct = total > 0 ? Math.round((wins / total) * 1000) / 10 : 50.0;

  return {
    pattern: day,
    wins,
    losses,
    total,
    winPct
  };
}

// Helper: Get combo wins from official data or dataset
export function getComboWins(de: string, day: string): number {
  const deVars = getPatternVariants(de);
  const dayVars = getPatternVariants(day);

  for (const d of deVars) {
    for (const dy of dayVars) {
      const c1 = `${d} | ${dy}`;
      const c2 = `${dy} | ${d}`;
      const top = OFFICIAL_TOP_COMBOS.find(c => c.combo === c1 || c.combo === c2);
      if (top) return top.wins;
    }
  }

  let count = 0;
  for (const g of HISTORICAL_GAMES) {
    if ((deVars.includes(g.winnerDE) && dayVars.includes(g.winnerDay)) || 
        (deVars.includes(g.winnerDay) && dayVars.includes(g.winnerDE))) {
      count++;
    }
  }
  return count;
}

// Helper: Search for historical precedent games between matching patterns
export function findPrecedents(
  team1DE: string,
  team1Day: string,
  team2DE: string,
  team2Day: string,
  team1Name?: string,
  team2Name?: string
): HistoricalGame[] {
  const matches: { game: HistoricalGame; score: number }[] = [];
  const t1DEVars = getPatternVariants(team1DE);
  const t1DayVars = getPatternVariants(team1Day);
  const t2DEVars = getPatternVariants(team2DE);
  const t2DayVars = getPatternVariants(team2Day);

  for (const g of HISTORICAL_GAMES) {
    let score = 0;

    // Direct head to head with same teams (moderate weight)
    if (team1Name && team2Name) {
      if ((g.winnerTeam === team1Name && g.loserTeam === team2Name) ||
          (g.winnerTeam === team2Name && g.loserTeam === team1Name)) {
        score += 8;
      }
    }

    // Exact pattern matchups
    const team1MatchedWinner = t1DEVars.includes(g.winnerDE) && t1DayVars.includes(g.winnerDay);
    const team2MatchedLoser = t2DEVars.includes(g.loserDE) && t2DayVars.includes(g.loserDay);
    if (team1MatchedWinner && team2MatchedLoser) score += 20;

    const team2MatchedWinner = t2DEVars.includes(g.winnerDE) && t2DayVars.includes(g.winnerDay);
    const team1MatchedLoser = t1DEVars.includes(g.loserDE) && t1DayVars.includes(g.loserDay);
    if (team2MatchedWinner && team1MatchedLoser) score += 20;

    // Partial pattern matches
    if (t1DEVars.includes(g.winnerDE) || t1DEVars.includes(g.loserDE)) score += 3;
    if (t2DEVars.includes(g.winnerDE) || t2DEVars.includes(g.loserDE)) score += 3;
    if (t1DayVars.includes(g.winnerDay) || t1DayVars.includes(g.loserDay)) score += 2;
    if (t2DayVars.includes(g.winnerDay) || t2DayVars.includes(g.loserDay)) score += 2;

    if (score >= 5) {
      matches.push({ game: g, score });
    }
  }

  // Sort by relevance score desc, then by date desc
  matches.sort((a, b) => b.score - a.score);
  return matches.slice(0, 10).map(m => m.game);
}
